<div class="card card-body" id="gps-live-diagnostics" data-url="{{ route('admin.gps-devices.diagnostics.live') }}" data-stream-url="{{ route('admin.gps-devices.diagnostics.stream') }}" data-buffer="{{ config('gps.live_diagnostic_buffer') }}">
  <div class="d-flex flex-wrap justify-content-between gap-3 mb-3"><div><h3 class="h5 mb-1">Live device registry & diagnostics</h3><p class="text-muted mb-0">Short-lived, authorized telemetry viewer. It never stores raw packet or ACK data in SQL, browser storage or logs.</p></div><div class="d-flex gap-2"><button class="btn btn-outline-secondary btn-sm" data-pause>Pause</button><button class="btn btn-outline-secondary btn-sm" data-clear>Clear</button><span class="badge text-bg-secondary" data-connection>Connecting</span></div></div>
  <div class="row g-3 mb-3"><div class="col-md-4"><label class="form-label" for="gps-diagnostic-device">Registered device</label><select id="gps-diagnostic-device" class="form-select"><option value="">All registered devices</option></select></div><div class="col-md-8"><div class="small text-muted pt-md-4" data-health>Checking runtime health…</div></div></div>
  <div class="table-responsive mb-4"><table class="table align-middle"><thead><tr><th>Device / assignment</th><th>Protocol / model evidence</th><th>Communication</th><th>Telemetry</th><th>GPS / power</th><th>Last packet</th></tr></thead><tbody data-rows><tr><td colspan="6" class="text-muted">Waiting for current state…</td></tr></tbody></table></div>
