</div>
<script>
(()=>{const root=document.getElementById('gps-live-diagnostics');if(!root)return;const sel=root.querySelector('#gps-diagnostic-device'),rows=root.querySelector('[data-rows]'),health=root.querySelector('[data-health]'),badge=root.querySelector('[data-connection]'),box=root.querySelector('[data-events]'),auto=root.querySelector('[data-autoscroll]'),pause=root.querySelector('[data-pause]');let stopped=false,paused=false,last=null,events=[],known=new Map();const max=Math.max(100,Math.min(1000,Number(root.dataset.buffer)||500)),e=v=>String(v??'—').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])),dt=v=>v?new Date(v).toLocaleString():'Never';const renderEvents=()=>{box.replaceChildren();if(!events.length){box.innerHTML='<small class="text-muted">Waiting for packets…</small>';return}events.forEach(x=>{const n=document.createElement('article');n.className='border-bottom py-2 small';n.innerHTML=`<strong>${e(x.event)}</strong> · ${e(dt(x.at))} · ${e(x.imei??'connection')}<pre class="mb-1 mt-1 text-wrap"></pre>`;n.querySelector('pre').textContent=JSON.stringify(x.fields,null,2);['raw_hex','ack_hex'].forEach(k=>{if(x.fields?.[k]){const b=document.createElement('button');b.className='btn btn-sm btn-outline-secondary me-1';b.textContent=`Copy ${k}`;b.onclick=()=>navigator.clipboard?.writeText(x.fields[k]);n.append(b)}});box.append(n)});if(auto.checked)box.scrollTop=box.scrollHeight};const state=async()=>{try{const u=new URL(root.dataset.url,location.origin);if(sel.value)u.searchParams.set('device_id',sel.value);const d=await (await fetch(u,{headers:{Accept:'application/json'},cache:'no-store'})).json();d.devices.forEach(x=>{if(x.device_id&&!known.has(x.device_id)){known.set(x.device_id,x);sel.insertAdjacentHTML('beforeend',`<option value="${x.device_id}">${e(x.registration??x.name)} · ${e(x.imei)}</option>`)}});rows.innerHTML=d.devices.length?d.devices.map(x=>`<tr><td><strong>${e(x.registration??x.name)}</strong><br><small>${e(x.imei)}</small></td><td>${e(x.configured_protocol)} · ${x.detected_protocol?'packet validated':'configured'}<br><small>Model: ${e(x.configured_model??'Unknown / unverified')}</small></td><td>${x.online?'Online':'Offline'}<br><small>TCP: ${x.connection_connected===true?'connected':x.connection_connected===false?'reconnecting':'unknown'}</small></td><td>${e(x.state)}<br><small>ACC: ${x.acc===true?'ON':x.acc===false?'OFF':'unknown'} · GPS: ${e(x.gps_state)}</small></td><td>${x.latitude!=null?`${Number(x.latitude).toFixed(6)}, ${Number(x.longitude).toFixed(6)}`:'No valid fix'}<br><small>${x.charging_current===true?'Charging':x.external_power_current===true?'External power':x.charging===true?`Last confirmed charging: ${e(dt(x.power_reported_at))}`:'Power not reported'}</small></td><td>${e(dt(x.last_packet_at))}</td></tr>`).join(''):'<tr><td colspan="6">No matching device.</td></tr>';const h=d.health,listener=h.receiver?.updated_at&&Date.now()-Date.parse(h.receiver.updated_at)<15000?'running':'stale';health.textContent=`TCP listener: ${listener} · Database: ${h.database.status}${h.database.latency_ms!=null?` ${h.database.latency_ms}ms`:''} · Redis: ${h.redis.status}${h.redis.latency_ms!=null?` ${h.redis.latency_ms}ms`:''} · Reverb: ${h.reverb.status} · Failed GPS jobs: ${h.failed_gps_jobs??'unknown'} · ${h.queues.map(q=>`${q.name}: ${q.available?`${q.depth} queued`:'unknown'}`).join(' · ')}`;badge.textContent='Live snapshot connected';badge.className='badge text-bg-success'}catch{badge.textContent='Reconnecting';badge.className='badge text-bg-warning'}finally{if(!stopped)setTimeout(state,5000)}};const stream=async()=>{if(!stopped&&!paused)try{const u=new URL(root.dataset.streamUrl,location.origin);if(sel.value)u.searchParams.set('device_id',sel.value);if(last)u.searchParams.set('after',last);const d=await (await fetch(u,{headers:{Accept:'application/json'},cache:'no-store'})).json();if(d.events.length){events.push(...d.events);events=events.slice(-max);last=d.events.at(-1).id;renderEvents()}}catch{}finally{if(!stopped)setTimeout(stream,1000)}};sel.onchange=()=>{last=null;events=[];renderEvents();state()};pause.onclick=()=>{paused=!paused;pause.textContent=paused?'Resume':'Pause'};root.querySelector('[data-clear]').onclick=()=>{last=null;events=[];renderEvents()};addEventListener('pagehide',()=>stopped=true,{once:true});state();stream()})();
</script>
